def check(call, view, history):
    if getattr(call, 'name', '') != 'run_command':
        return None
    args = getattr(call, 'args', {}) or {}
    cmd = args.get('cmd', '')
    if not isinstance(cmd, str):
        return None
    low = cmd.lower()

    # Web deployment failure: after creating/pushing hello.html, do not reset the
    # bare repo or webroot in a way that removes the required published file.
    destructive_webroot = ('/var/www/html' in cmd and ('rm -rf' in low or 'rm -r ' in low or 'rm -f ' in low))
    resets_git_server = ('/git/server' in cmd and 'rm -rf' in low and 'git init --bare' in low)
    if destructive_webroot or resets_git_server:
        saw_hello_work = False
        for ev in history or []:
            p = getattr(ev, 'payload', {}) or {}
            s = str(p)
            if 'hello.html' in s and ('git push' in s or '/var/www/html' in s or 'post-receive' in s):
                saw_hello_work = True
                break
        if saw_hello_work:
            return 'Do not delete or reset the already-published hello.html/webroot state. Leave required outputs in place; if you reset, immediately republish and verify /var/www/html/hello.html exists before finishing.'

    # VM/BMP failure: running the VM and checking only BMP validity is not enough
    # for tasks whose tests compare the produced frame to a reference.
    runs_vm = 'node vm.js' in low and 'frame.bmp' in low
    superficial_bmp_check = ("b'BM'" in cmd or 'struct.unpack' in cmd or 'getsize' in low or 'ls -l /tmp/frame.bmp' in low)
    has_reference_check = any(x in low for x in ['reference', 'expected', 'similar', 'compare', 'mse', 'pixel', 'imagechops', 'pytest', 'test_outputs'])
    if runs_vm and superficial_bmp_check and not has_reference_check:
        return 'Do not treat a valid BMP header/size or VM stdout as sufficient. Run the task tests or compare /tmp/frame.bmp pixel output against the reference/expected frame, then fix the generator if it differs.'
    return None

def check(call, view, history):
    if call.name != 'run_command':
        return None
    cmd = (call.args or {}).get('cmd') or ''
    if not isinstance(cmd, str):
        return None
    changed = any((f or {}).get('path') == '/app/gpt2.c' for f in (view.get('files_changed') or []))
    if not changed:
        return None
    runs_gpt2_binary = ('/app/a.out' in cmd or './a.out' in cmd) and '/app/gpt2-124M.ckpt' in cmd
    mentions_gpt2_c = '/app/gpt2.c' in cmd or 'gpt2.c' in cmd
    invokes_required_test = 'test_outputs.py::test_gpt2_implementation' in cmd or ('pytest' in cmd and 'test_outputs.py' in cmd)
    if runs_gpt2_binary and mentions_gpt2_c and not invokes_required_test:
        return 'Manual compile/run only proves the program executes; run the exact output-correctness test test_outputs.py::test_gpt2_implementation instead, or include an explicit comparison against its expected output.'
    return None

def check(call, view, history):
    if call.name != 'run_command':
        return None
    if view.get('task') != 'gpt2-codegolf':
        return None
    changed = view.get('files_changed') or []
    gpt2 = None
    for f in changed:
        if f.get('path') == '/app/gpt2.c':
            gpt2 = f
            break
    if not gpt2 or (gpt2.get('size') is not None and gpt2.get('size') >= 5000):
        return None
    # Has the required implementation test already been executed and passed?
    for ev in history:
        if getattr(ev, 'kind', None) != 'tool_result':
            continue
        payload = getattr(ev, 'payload', {}) or {}
        res = (payload.get('result') or {}).get('data') or {}
        out = res.get('output') or ''
        if res.get('exit_code') == 0 and 'test_outputs.py::test_gpt2_implementation' in out and ('PASSED' in out or ' passed' in out or '[100%]' in out):
            return None
    cmd = (call.args or {}).get('cmd') or ''
    validation_markers = ['pytest', 'test_outputs.py', 'test_gpt2_implementation']
    compile_markers = ['gcc', 'cc ', 'clang']
    if any(m in cmd for m in validation_markers) or any(m in cmd for m in compile_markers):
        return None
    if 'gpt2-124M.ckpt' in cmd or 'perl -e' in cmd or 'inspect' in cmd:
        return 'gpt2.c is present and under the size limit, but the required correctness test has not passed yet. Run `pytest -q test_outputs.py::test_gpt2_implementation` next; only continue inspecting after observing that test outcome.'
    return None

def check(call, view, history):
    if getattr(call, 'name', None) != 'run_command':
        return None
    args = getattr(call, 'args', {}) or {}
    cmd = args.get('cmd') or ''
    files = view.get('files_changed') or []
    paths = []
    for f in files:
        if isinstance(f, dict):
            paths.append(f.get('path') or '')
    touched_git_deploy = any(p.startswith('/git/server') or p.startswith('/var/www/server') for p in paths)
    touched_doom_binary = any(p == '/app/doomgeneric_mips' or p.endswith('/doomgeneric_mips') for p in paths)

    if touched_git_deploy and 'curl' in cmd and '8080' in cmd and '/git/server' in cmd and 'hello.html' not in cmd:
        return 'This only smoke-tests the server/repo. Verify the exact required deployed artifact instead: push or create the expected hello.html and check its served path/content before finishing.'

    robust_terms = ['pytest', 'test_outputs.py', 'reference', 'compare', 'similar', 'ImageChops', 'pixel', 'cmp ', 'diff ', 'sha256sum']
    if touched_doom_binary and 'node vm.js' in cmd and '/tmp/frame.bmp' in cmd and not any(t in cmd for t in robust_terms):
        return 'This only proves that a BMP file exists. Validate the generated frame against the expected/reference output or run the task tests before finishing.'
    return None
